 static <E> ImmutableMultiset<E> create(Collection<? extends Entry<? extends E>> entries) {
     int distinct = entries.size();
     @SuppressWarnings({"unchecked", "rawtypes"})
     ImmutableEntry<E>[] entryArray = new ImmutableEntry[distinct];
